def _proc(uid: int = 1001) -> dict[str, Any]:
    return {
        "executable": "/runtime/bin/python",
        "argv_template": ["python", "-m", "x"],
        "cwd": "/fixture",
        "environment": {"LANG": "C.UTF-8"},
        "inherited_fd_roles": [],
        "network_policy": "none",
        "uid": uid,
        "gid": uid,
        "seccomp_filter_sha256": None,
    }


def _freshness() -> dict[str, Any]:
    return {
        "boot_id": "boot-1",
        "authority_snapshot_id": "snap2_fixture",
        "sampled_wall_time": TS,
        "sampled_boottime_ns": 1,
        "snapshot_deadline_boottime_ns": 2,
        "clock_review_ref": "clock_aaa",
    }


def _mount(role: str = "runtime", mode: str = "ro") -> dict[str, Any]:
    return {
        "source_role": role,
        "destination": "/mnt/x",
        "mode": mode,
        "max_bytes": None,
    }


